def render_icon(
    name: str,
    size: int = 18,
    color: str = "currentColor",
    class_name: str = "",
    stroke_width: float = 2.0,
) -> str:
    """Generate an inline SVG string for the requested icon name.
    
    Falls back gracefully to 'leaf' if the requested icon is not in the catalog.
    """
    clean_name = name.lower().strip()
    paths = ICON_PATHS.get(clean_name, ICON_PATHS.get("leaf", ""))
    css_class = f' class="{class_name}"' if class_name else ""
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" '
        f'viewBox="0 0 24 24" fill="none" stroke="{color}" stroke-width="{stroke_width}" '
        f'stroke-linecap="round" stroke-linejoin="round"{css_class} '
        f'style="display:inline-block; vertical-align:middle; flex-shrink:0;">'
        f'{paths}</svg>'
    )

